-- Update: devon-achane surgery 2026-11-11
INSERT INTO progress_updates (injury_id, update_date, stage, status_label, notes, source)
SELECT i.id, '2026-11-11', 'surgery', 'Surgery done; rehab under way', 'Dolphins head coach Jeff Hafley said on Nov. 11: "He had his surgery. He''s in the training room every morning." He is in the weight room and doing rehab. The surgery date was not given.', 'https://www.miamidolphins.com/news/transcript-hc-jeff-hafley-press-conference-november-11'
FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'devon-achane' AND p.league = 'NFL' AND i.injury_type = 'ACL' AND i.injury_date = '2026-09-27'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'surgery' AND x.update_date = '2026-11-11');

